import { cn } from '@/react/lib/cn'

// How far a task has got: a white bar on a 6px #141414 track with round ends. The fill slides to a new value over
// 320ms on the strong ease-out, on transform only. Leave out `value` when the end is not known: a short white bar
// sweeps across the track at a steady pace, and with reduced motion it rests and breathes instead. `label` names it
// for assistive tech (a progressbar); say the number in text beside it too.
export interface ProgressProps {
  /** How far, from 0 to max; leave it out for work with no known end. */
  value?: number | null
  /** The value that means done. */
  max?: number
  /** What is in progress, for assistive tech. */
  label?: string
  className?: string
}

export function Progress({ value, max = 100, label, className }: ProgressProps) {
  const known = typeof value === 'number'
  const share = known ? Math.max(0, Math.min(1, value / (max || 1))) : 0
  return (
    <>
      <style href="ds-progress" precedence="ds">{css}</style>
      <div
        data-ds="progress"
        role="progressbar"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={known ? value : undefined}
        className={cn('relative h-1.5 w-full overflow-hidden rounded-full bg-edge-strong', className)}
      >
        {known
          ? <div className="h-full w-full rounded-full bg-fg transition-transform duration-350 ease-out motion-reduce:transition-none" style={{ transform: `translateX(-${(1 - share) * 100}%)` }} />
          : <div className="ds-progress-sweep h-full w-2/5 rounded-full bg-fg" />}
      </div>
    </>
  )
}

export default Progress

const css = `
.ds-progress-sweep { animation: ds-progress-sweep 1.5s var(--ds-easing-in-out) infinite; }
@keyframes ds-progress-sweep { from { transform: translateX(-100%); } to { transform: translateX(250%); } }
@keyframes ds-progress-breathe { 50% { opacity: 0.5; } }
@media (prefers-reduced-motion: reduce) { .ds-progress-sweep { width: 100%; animation: ds-progress-breathe 2s var(--ds-easing-in-out) infinite; } }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

